import { useState, useEffect } from 'react';
import { Dialog, DialogPanel } from '@headlessui/react';
import { Bars3Icon, XMarkIcon } from '@heroicons/react/24/outline';
import ThemeToggle from '../components/theme';

const navigation = [
    { name: 'Home', href: '#' },
    { name: 'About', href: '#about' },
    { name: 'Skills', href: '#skills' },
    { name: 'Experience', href: '#experience' },
    { name: 'Projects', href: '#projects' },
    { name: 'Contact', href: '#contact' },
]

export default function Header() {
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [isBlurred, setIsBlurred] = useState(false);

    // Smooth scroll function
    const handleSmoothScroll = (e, href) => {
        e.preventDefault();
        
        if (href === '#') {
            // Scroll to top for Home link
            window.scrollTo({
                top: 0,
                behavior: 'smooth'
            });
        } else {
            // Scroll to specific section
            const targetElement = document.querySelector(href);
            if (targetElement) {
                const offsetTop = targetElement.offsetTop - 100; // Account for fixed header
                window.scrollTo({
                    top: offsetTop,
                    behavior: 'smooth'
                });
            }
        }
        
        // Close mobile menu after clicking
        setMobileMenuOpen(false);
    };

    useEffect(() => {

        const handleScroll = () => {
            const currentScrollTop = document.documentElement.scrollTop;

            if (currentScrollTop > 0) {
                // User is scrolling up, apply blur to header
                setIsBlurred(true);
            } else {
                // User is scrolling down, remove blur
                setIsBlurred(false);
            }
        };

        window.addEventListener("scroll", handleScroll);

        return () => {
            window.removeEventListener("scroll", handleScroll);
        };
    }, []);

    return (
        <header className={`fixed top-0 left-0 right-0 z-50 w-full transition-all duration-300`}>
            <div className="flex justify-center w-full">
                <nav aria-label="Global"
                    className={`w-11/12 mt-2 flex items-center justify-between p-4 lg:px-8 ${isBlurred ? "backdrop-blur-lg bg-white/90 transition delay-400 duration-500 rounded-t-lg rounded-b-lg dark:bg-slate-800/90" : "transition delay-400 duration-500 bg-transparent"}`}
                >
                    <div className="flex lg:flex-1">
                        <span className='font-bold text-gray-900 sm:text-2xl text-black-300 dark:text-white'>Ragavan</span>
                    </div>
                    <div className="flex lg:hidden gap-4">
                        <ThemeToggle/>
                        
                        <button
                            type="button"
                            onClick={() => setMobileMenuOpen(true)}
                            className="-m-2.5 inline-flex items-center justify-center rounded-md p-2.5 text-gray-700 cursor-pointer"
                        >
                            <span className="sr-only">Open main menu</span>
                            <Bars3Icon aria-hidden="true" className="h-6 w-6" />
                        </button>
                    </div>
                    <div className="hidden lg:flex lg:gap-x-12">
                        {navigation.map((item) => (
                            <a 
                                key={item.name} 
                                href={item.href} 
                                onClick={(e) => handleSmoothScroll(e, item.href)}
                                className="text-1xl font-semibold leading-6 text-gray-900 dark:text-white cursor-pointer hover:text-purple-600 dark:hover:text-purple-400 transition-colors duration-300"
                            >
                                {item.name}
                            </a>
                        ))}
                    </div>

                    <div className="hidden lg:flex lg:flex-1 lg:justify-end">
                        <ThemeToggle/>
                        
                        <a 
                            href="#contact" 
                            onClick={(e) => handleSmoothScroll(e, '#contact')}
                            className="hidden cursor-pointer lg:flex items-center gap-3 px-10 py-2.5 border border-gray-500 rounded-full ml-4 font-Ovo dark:border-white/50 hover:border-purple-500 hover:text-purple-600 dark:hover:border-purple-400 dark:hover:text-purple-400 transition-colors duration-300"
                        >
                            Contact
                            <img src="data:image/png;base64," alt="" className="w-3 dark:hidden" />
                            <img src="data:image/png;base64," alt="" className="w-3 hidden dark:block" />
                        </a>
                    </div>
                </nav>
            </div>
            <Dialog open={mobileMenuOpen} onClose={setMobileMenuOpen} className="lg:hidden">
                <div className="fixed inset-0 z-50" />
                <DialogPanel className="fixed inset-y-0 right-0 z-50 w-full overflow-y-auto bg-white px-6 py-6 sm:max-w-sm sm:ring-1 sm:ring-gray-900/10">
                    <div className="flex items-center justify-between">
                        <a href="#" onClick={(e) => handleSmoothScroll(e, '#')} className="-m-1.5 p-1.5">
                            <span className="sr-only">Ragavan Portfolio</span>
                            <span className='font-bold text-purple-600 text-xl'>Ragavan</span>
                        </a>
                        <button
                            type="button"
                            onClick={() => setMobileMenuOpen(false)}
                            className="-m-2.5 rounded-md p-2.5 text-gray-700"
                        >
                            <span className="sr-only">Close menu</span>
                            <XMarkIcon aria-hidden="true" className="h-6 w-6" />
                        </button>
                    </div>
                    <div className="mt-6 flow-root">
                        <div className="-my-6 divide-y divide-gray-500/10">
                            <div className="space-y-2 py-6">
                                {navigation.map((item) => (
                                    <a
                                        key={item.name}
                                        href={item.href}
                                        onClick={(e) => handleSmoothScroll(e, item.href)}
                                        className="-mx-3 block rounded-lg px-3 py-2 text-2xl font-semibold leading-7 text-gray-900 hover:bg-gray-50 hover:text-purple-600 transition-colors duration-300"
                                    >
                                        {item.name}
                                    </a>
                                ))}
                            </div>
                            <div className="py-6">
                                <button class="rounded-full ...">Save Changes</button>
                            </div>
                        </div>
                    </div>
                </DialogPanel>
            </Dialog>
        </header>
    )
}
